% Solver generated by SolverMapp
clear; clc;

%% Stage 0: Inputs and start values of state variables
G          = 1; % [Input] (m^3/(kg s^2)) Gravitational constant (normalised)
m_2        = 1; % [Input] (kg) Mass of body 2
m_3        = 1; % [Input] (kg) Mass of body 3
m_1        = 1; % [Input] (kg) Mass of body 1
v_1        = [0.466203685; 0.43236573]; % [State] (m/s) Velocity of body 1
r_1        = [0.97000436; -0.24308753]; % [State] (m) Position of body 1
v_2        = [0.466203685; 0.43236573]; % [State] (m/s) Velocity of body 2
r_2        = [-0.97000436; 0.24308753]; % [State] (m) Position of body 2
v_3        = [-0.93240737; -0.86473146]; % [State] (m/s) Velocity of body 3
r_3        = [0; 0]; % [State] (m) Position of body 3

%% Stage 1
% --- ODE system: r_1, r_2, r_3, v_1, v_2, v_3 over t: RK4, 2000 steps ---
% Position of body 1: \frac{d\mathbf{r}_1}{dt} = \mathbf{v}_1
% Position of body 2: \frac{d\mathbf{r}_2}{dt} = \mathbf{v}_2
% Position of body 3: \frac{d\mathbf{r}_3}{dt} = \mathbf{v}_3
% Velocity of body 1: \frac{d\mathbf{v}_1}{dt} = G m_2 \frac{\mathbf{r}_2 - \mathbf{r}_1}{\|\mathbf{r}_2 - \mathbf{r}_1\|^3} + G m_3 \frac{\mathbf{r}_3 - \mathbf{r}_1}{\|\mathbf{r}_3 - \mathbf{r}_1\|^3}
% Velocity of body 2: \frac{d\mathbf{v}_2}{dt} = G m_1 \frac{\mathbf{r}_1 - \mathbf{r}_2}{\|\mathbf{r}_1 - \mathbf{r}_2\|^3} + G m_3 \frac{\mathbf{r}_3 - \mathbf{r}_2}{\|\mathbf{r}_3 - \mathbf{r}_2\|^3}
% Velocity of body 3: \frac{d\mathbf{v}_3}{dt} = G m_1 \frac{\mathbf{r}_1 - \mathbf{r}_3}{\|\mathbf{r}_1 - \mathbf{r}_3\|^3} + G m_2 \frac{\mathbf{r}_2 - \mathbf{r}_3}{\|\mathbf{r}_2 - \mathbf{r}_3\|^3}
t = 0;
h_rk = (6.32591398 - t) / 2000;
% Solution every 10 steps -> ode_system_1.csv
fid_ode1 = fopen('ode_system_1.csv', 'w');
head_ode = 't';
head_ode = [head_ode, sprintf(',r_1[%d]', 1:numel(r_1))];
head_ode = [head_ode, sprintf(',r_2[%d]', 1:numel(r_2))];
head_ode = [head_ode, sprintf(',r_3[%d]', 1:numel(r_3))];
head_ode = [head_ode, sprintf(',v_1[%d]', 1:numel(v_1))];
head_ode = [head_ode, sprintf(',v_2[%d]', 1:numel(v_2))];
head_ode = [head_ode, sprintf(',v_3[%d]', 1:numel(v_3))];
fprintf(fid_ode1, '%s\n', head_ode);
row_ode = [t, r_1(:).', r_2(:).', r_3(:).', v_1(:).', v_2(:).', v_3(:).'];
fprintf(fid_ode1, [repmat('%.17g,', 1, numel(row_ode) - 1), '%.17g\n'], row_ode);
w_rk = [1, 2, 2, 1]; c_rk = [0.5, 0.5, 1];
for step = 1:2000
    t_rk0 = t;
    r_1_rk0 = r_1; r_1_acc = 0;
    r_2_rk0 = r_2; r_2_acc = 0;
    r_3_rk0 = r_3; r_3_acc = 0;
    v_1_rk0 = v_1; v_1_acc = 0;
    v_2_rk0 = v_2; v_2_acc = 0;
    v_3_rk0 = v_3; v_3_acc = 0;
    for stage = 1:4
        r_1_rate = v_1;
        r_2_rate = v_2;
        r_3_rate = v_3;
        v_1_rate = G * m_2 * ((r_2 - r_1) / norm(r_2 - r_1)^3) + G * m_3 * ((r_3 - r_1) / norm(r_3 - r_1)^3);
        v_2_rate = G * m_1 * ((r_1 - r_2) / norm(r_1 - r_2)^3) + G * m_3 * ((r_3 - r_2) / norm(r_3 - r_2)^3);
        v_3_rate = G * m_1 * ((r_1 - r_3) / norm(r_1 - r_3)^3) + G * m_2 * ((r_2 - r_3) / norm(r_2 - r_3)^3);
        r_1_acc = r_1_acc + w_rk(stage) * r_1_rate;
        r_2_acc = r_2_acc + w_rk(stage) * r_2_rate;
        r_3_acc = r_3_acc + w_rk(stage) * r_3_rate;
        v_1_acc = v_1_acc + w_rk(stage) * v_1_rate;
        v_2_acc = v_2_acc + w_rk(stage) * v_2_rate;
        v_3_acc = v_3_acc + w_rk(stage) * v_3_rate;
        if stage < 4
            t = t_rk0 + c_rk(stage) * h_rk;
            r_1 = r_1_rk0 + c_rk(stage) * h_rk * r_1_rate;
            r_2 = r_2_rk0 + c_rk(stage) * h_rk * r_2_rate;
            r_3 = r_3_rk0 + c_rk(stage) * h_rk * r_3_rate;
            v_1 = v_1_rk0 + c_rk(stage) * h_rk * v_1_rate;
            v_2 = v_2_rk0 + c_rk(stage) * h_rk * v_2_rate;
            v_3 = v_3_rk0 + c_rk(stage) * h_rk * v_3_rate;
        end
    end
    t = t_rk0 + h_rk;
    r_1 = r_1_rk0 + h_rk / 6 * r_1_acc;
    r_2 = r_2_rk0 + h_rk / 6 * r_2_acc;
    r_3 = r_3_rk0 + h_rk / 6 * r_3_acc;
    v_1 = v_1_rk0 + h_rk / 6 * v_1_acc;
    v_2 = v_2_rk0 + h_rk / 6 * v_2_acc;
    v_3 = v_3_rk0 + h_rk / 6 * v_3_acc;
    if mod(step, 10) == 0
        row_ode = [t, r_1(:).', r_2(:).', r_3(:).', v_1(:).', v_2(:).', v_3(:).'];
        fprintf(fid_ode1, [repmat('%.17g,', 1, numel(row_ode) - 1), '%.17g\n'], row_ode);
    end
end
fclose(fid_ode1);

%% Stage 2
% [EXPLICIT] Total energy: E = \frac{1}{2} m_1 \|\mathbf{v}_1\|^2 + \frac{1}{2} m_2 \|\mathbf{v}_2\|^2 + \frac{1}{2} m_3 \|\mathbf{v}_3\|^2 - \frac{G m_1 m_2}{\|\mathbf{r}_1 - \mathbf{r}_2\|} - \frac{G m_1 m_3}{\|\mathbf{r}_1 - \mathbf{r}_3\|} - \frac{G m_2 m_3}{\|\mathbf{r}_2 - \mathbf{r}_3\|}
E = 1 / 2 * m_1 * norm(v_1)^2 + 1 / 2 * m_2 * norm(v_2)^2 + 1 / 2 * m_3 * norm(v_3)^2 - G * m_1 * m_2 / norm(r_1 - r_2) - G * m_1 * m_3 / norm(r_1 - r_3) - G * m_2 * m_3 / norm(r_2 - r_3);

%% Results
fprintf('%-12s = %s\n', 'v_1', mat2str(v_1));
fprintf('%-12s = %s\n', 't', mat2str(t));
fprintf('%-12s = %s\n', 'r_1', mat2str(r_1));
fprintf('%-12s = %s\n', 'v_2', mat2str(v_2));
fprintf('%-12s = %s\n', 'r_2', mat2str(r_2));
fprintf('%-12s = %s\n', 'v_3', mat2str(v_3));
fprintf('%-12s = %s\n', 'r_3', mat2str(r_3));
fprintf('%-12s = %s\n', 'G', mat2str(G));
fprintf('%-12s = %s\n', 'm_2', mat2str(m_2));
fprintf('%-12s = %s\n', 'm_3', mat2str(m_3));
fprintf('%-12s = %s\n', 'm_1', mat2str(m_1));
fprintf('%-12s = %s\n', 'E', mat2str(E));